/** The server HTML of the Basics island, as renderPage writes it; both halves of the basics-island tests pin it. */
export const basicsIsland = (plus: string) =>
  `<weft-island data-id="Basics" data-when="load"><script type="application/json">{}</script><!--{--><!--{--><div class="weft-container"><!--[-->` +
  `<!--{--><button class="weft-button" type="button" data-variant="solid" data-tone="primary" data-size="md"><span class="weft-button__content"><!--(--><svg class="weft-icon" xmlns="http://www.w3.org/2000/svg" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${plus}</svg><!--)--><!--(--><span class="weft-button__label">Step</span><!--)--><!--(--><!----><!--)--></span><!----></button><!--}-->` +
  `<!--{--><button class="weft-button" type="button" data-variant="outline" data-tone="primary" data-size="md"><span class="weft-button__content"><!--(--><!----><!--)--><!--(--><span class="weft-button__label">Busy</span><!--)--><!--(--><!----><!--)--></span><!----></button><!--}-->` +
  `<a class="weft-link" href="/"><!--[-->Home<!--]--></a>` +
  `<a class="weft-link" href="https://vuejs.org/" rel="noopener"><!--[-->Vue<!--]--></a>` +
  `<span class="weft-badge" data-variant="soft" data-tone="success" data-size="md"><!----><!--(-->1<!--)--><!----></span><div class="weft-avatar-group" role="group" data-size="md" aria-label="Team"><!--[--><span class="weft-avatar" data-size="md" role="img" aria-label="Ada Lovelace"><!--[1--><span class="weft-avatar__initials" aria-hidden="true">AL</span><!--]--></span><span class="weft-avatar" data-size="md" role="img" aria-label="Grace Hopper"><!--[1--><span class="weft-avatar__initials" aria-hidden="true">GH</span><!--]--></span><!----><!--]--><span class="weft-avatar weft-avatar-group__more" data-size="md"><span aria-hidden="true">+1</span><span class="weft-visually-hidden">1 more</span></span></div><span class="weft-chip"><!--[--><kbd class="weft-kbd" data-size="md"><!--(--><!--[0--><span aria-hidden="true">⌘</span><span class="weft-visually-hidden">Command</span><!--]--><!--)--></kbd><!--]--><span class="weft-chip__indicator" data-tone="danger" data-size="md" data-position="top-end" data-text="true">1</span><!----></span><div class="weft-separator" role="separator" aria-orientation="horizontal" aria-label="or" data-orientation="horizontal"><span class="weft-separator__line"></span><!--[--><span class="weft-separator__content"><!----><!--(-->or<!--)--></span><span class="weft-separator__line"></span><!--]--></div>` +
  `<div class="weft-progress" role="progressbar" aria-label="Steps" aria-valuemin="0" aria-valuemax="4" aria-valuenow="1" data-state="determinate" data-tone="primary" data-size="md"><div class="weft-progress__track"><div class="weft-progress__bar" style="inline-size:25%;"></div></div><span class="weft-progress__status">25%</span></div>` +
  `<div class="weft-progress" role="progressbar" aria-label="Waiting" aria-valuemin="0" aria-valuemax="100" data-state="indeterminate" data-tone="primary" data-size="md"><div class="weft-progress__track"><div class="weft-progress__bar" style=""></div></div><!----></div>` +
  `<span class="weft-spinner" role="status"><span class="weft-spinner__ring"></span><span class="weft-visually-hidden">Working</span></span>` +
  `<span class="weft-skeleton" aria-hidden="true" style="inline-size:4rem;"></span><!--]--></div><!--}--><!--}--></weft-island>`
